SELECT 'delete' what, count(*) found,
  count(*) FILTER (WHERE u.role = 'ADMIN' AND b.claimed_session_id IS NULL) deletable,
  (SELECT count(*) FROM challenge_quiz_question_bank lq JOIN study_packs lsp ON lsp.id = lq.study_pack_id JOIN notes ln ON ln.id = lsp.note_id
     JOIN study_packs osp ON osp.note_id = ln.copied_from_note_id JOIN challenge_quiz_question_bank b2 ON b2.study_pack_id = osp.id AND b2.question_key = lq.question_key
     WHERE b2.id IN (SELECT id FROM d) AND lq.id <> b2.id) learner_copies
FROM d JOIN challenge_quiz_question_bank b ON b.id = d.id JOIN users u ON u.id = b.user_id;

-- Learner copy of fixed template cdc9879d (answered 2026-09-05; last_known_outcome left as history, owner decision 4)
WITH lfix(id, target, keyed) AS (VALUES ('e4a1421e-791c-409f-aac9-5b26dae0b364'::uuid, 'TF', 'TT')),
lt AS (
  SELECT f.id, (b.question->>'correctIndex')::int old_index,
    (SELECT (o.i - 1)::int FROM jsonb_array_elements_text(b.question->'choices') WITH ORDINALITY o(c, i) WHERE CASE f.target WHEN 'TT' THEN o.c ~* '^([a-d][:.)]\s*)?both' WHEN 'TF' THEN o.c ~* 'only statement\s*(1|i)\M' WHEN 'FT' THEN o.c ~* 'only statement\s*(2|ii)\M' WHEN 'FF' THEN o.c ~* '^([a-d][:.)]\s*)?neither' END) new_index,
    (SELECT (o.i - 1)::int FROM jsonb_array_elements_text(b.question->'choices') WITH ORDINALITY o(c, i) WHERE CASE f.keyed WHEN 'TT' THEN o.c ~* '^([a-d][:.)]\s*)?both' WHEN 'TF' THEN o.c ~* 'only statement\s*(1|i)\M' WHEN 'FT' THEN o.c ~* 'only statement\s*(2|ii)\M' WHEN 'FF' THEN o.c ~* '^([a-d][:.)]\s*)?neither' END) keyed_index
  FROM lfix f JOIN challenge_quiz_question_bank b ON b.id = f.id JOIN users u ON u.id = b.user_id AND u.role <> 'ADMIN')
SELECT 'learner_fix' what, count(*) found, count(*) FILTER (WHERE new_index IS NOT NULL AND new_index <> old_index AND keyed_index = old_index) will_change FROM lt;

