t AS (
  SELECT f.id, (b.question->>'correctIndex')::int old_index,
    (SELECT (o.i - 1)::int FROM jsonb_array_elements_text(b.question->'choices') WITH ORDINALITY o(c, i) WHERE CASE f.target WHEN 'TT' THEN o.c ~* '^([a-d][:.)]\s*)?both' WHEN 'TF' THEN o.c ~* 'only statement\s*(1|i)\M' WHEN 'FT' THEN o.c ~* 'only statement\s*(2|ii)\M' WHEN 'FF' THEN o.c ~* '^([a-d][:.)]\s*)?neither' END) new_index,
    (SELECT (o.i - 1)::int FROM jsonb_array_elements_text(b.question->'choices') WITH ORDINALITY o(c, i) WHERE CASE f.keyed WHEN 'TT' THEN o.c ~* '^([a-d][:.)]\s*)?both' WHEN 'TF' THEN o.c ~* 'only statement\s*(1|i)\M' WHEN 'FT' THEN o.c ~* 'only statement\s*(2|ii)\M' WHEN 'FF' THEN o.c ~* '^([a-d][:.)]\s*)?neither' END) keyed_index
  FROM fix f JOIN challenge_quiz_question_bank b ON b.id = f.id JOIN users u ON u.id = b.user_id AND u.role = 'ADMIN')
UPDATE challenge_quiz_question_bank q SET question = jsonb_set(q.question, '{correctIndex}', to_jsonb(t.new_index))
FROM t WHERE q.id = t.id AND t.new_index IS NOT NULL AND t.new_index <> t.old_index AND t.keyed_index = t.old_index;
