  FROM lfix f JOIN challenge_quiz_question_bank b ON b.id = f.id JOIN users u ON u.id = b.user_id AND u.role <> 'ADMIN')
UPDATE challenge_quiz_question_bank q SET question = jsonb_set(q.question, '{correctIndex}', to_jsonb(lt.new_index))
FROM lt WHERE q.id = lt.id AND lt.new_index IS NOT NULL AND lt.new_index <> lt.old_index AND lt.keyed_index = lt.old_index;
